const rawInput = $input.item.json.influencer_list || '@diegodoal, @ibaillanos';
const selectedModel = $input.item.json.modelo_gemini || 'gemini-3.5-flash-lite';

const profiles = rawInput
  .split(/[,\n\s]+/)
  .map(handle => handle.replace('@', '').trim().toLowerCase())
  .filter(handle => handle.length > 0);

return profiles.map(profile => ({
  json: { profile, selectedModel }
}));

const initialProfiles = $('2. Separar Lista').all();
const allVideos = $input.all().map(i => i.json);

const output = [];

for (let i = 0; i < initialProfiles.length; i++) {
  const config = initialProfiles[i].json;
  const targetProfile = config.profile;

  const targetVideos = allVideos.filter(v => {
    const author = (v.authorMeta?.name || v.author || '').toLowerCase();
    return author.includes(targetProfile) || targetProfile.includes(author);
  });

  const pool = targetVideos.length > 0 ? targetVideos : allVideos;

  // FILTRO ANTI-PUBLI
  const nonSponsored = pool.filter(item => {
    if (item.isSponsored === true) return false;
    const text = (item.text || item.caption || item.desc || '').toLowerCase();
    const adKeywords = ['#publi', '#ad', '#advertisement', 'patrocinado', 'colaboracion', 'colaboración', '#sponsor', '#sponsored'];
    return !adKeywords.some(kw => text.includes(kw));
  });

  const validItems = nonSponsored.length > 0 ? nonSponsored : pool;
  const selected = validItems.length > 0 ? validItems[Math.floor(Math.random() * validItems.length)] : {};

  const author = selected.authorMeta?.name || selected.author || targetProfile;
  const fullCaption = selected.text || selected.caption || selected.desc || 'Sin descripción';
  const videoUrl = selected.webVideoUrl || (selected.id ? `https://www.tiktok.com/@${author}/video/${selected.id}` : `https://www.tiktok.com/@${author}`);
  const audioUrl = selected.musicMeta?.playUrl || null;

  output.push({
    json: {
      author: author,
      caption: fullCaption.substring(0, 400),
      videoUrl: videoUrl,
      audioUrl: audioUrl,
      selectedModel: config.selectedModel || 'gemini-3.5-flash-lite'
    }
  });
}

return output;

const metaItems = $('Sub-Flujo: 1. Extraer URL Audio').all();
const results = [];

for (let i = 0; i < $input.all().length; i++) {
  const item = $input.all()[i];
  const metaData = metaItems[i]?.json || {};

  let base64Str = '';
  let mimeType = 'video/mp4';

  if (item.binary && item.binary.data) {
    mimeType = item.binary.data.mimeType || 'video/mp4';
    // Usar el helper nativo de n8n para obtener el buffer aunque esté en filesystem-v2
    const buffer = await this.helpers.getBinaryDataBuffer(i, 'data');
    base64Str = buffer.toString('base64');
  }

  results.push({
    json: {
      author: metaData.author,
      caption: metaData.caption,
      videoUrl: metaData.videoUrl,
      selectedModel: metaData.selectedModel,
      base64Data: base64Str,
      mimeType: mimeType
    }
  });
}

return results;

