const geminiItems = $input.all();
const prepItems = $('Sub-Flujo: 3. Preparar Base64').all();
const output = [];

for (let i = 0; i < geminiItems.length; i++) {
  const transcriptionResp = geminiItems[i].json;
  const metaData = prepItems[i]?.json || {};

  let audioTranscription = '';
  const rawText = transcriptionResp.candidates?.[0]?.content?.parts?.[0]?.text;
  if (rawText) {
    audioTranscription = rawText.trim();
  }

  const prompt = [
    'Analiza la información de este contenido de TikTok para redactar un mensaje de outreach.',
    `Transcripción literal del audio del vídeo: "${audioTranscription || 'Sin transcripción disponible'}"`,
    `Texto de la descripción: "${metaData.caption}"`,
    'Extrae una frase hiper-natural, desenfadada y corta (máximo 8 palabras) sobre la idea central o el chascarrillo hablado del vídeo. Debe sonar espontánea para encajar tras: "estaba viendo tu vídeo sobre [resumen]".',
    'Responde UNICAMENTE un JSON válido: {"video_topic_phrase": "frase resumiendo el tema o chascarrillo"}'
  ].join('\n');

  output.push({
    json: {
      author: metaData.author,
      videoUrl: metaData.videoUrl,
      transcription: audioTranscription,
      selectedModel: metaData.selectedModel,
      geminiPayload: {
        contents: [{ parts: [{ text: prompt }] }],
        generationConfig: {
          responseMimeType: 'application/json',
          maxOutputTokens: 200
        }
      }
    }
  });
}

return output;

const geminiItems = $input.all();
const prepPromptItems = $('6. Preparar Prompt Final').all();
const results = [];

for (let i = 0; i < geminiItems.length; i++) {
  const geminiResp = geminiItems[i].json;
  const prepData = prepPromptItems[i]?.json || {};

  let topicPhrase = 'tu último vídeo';
  const rawText = geminiResp.candidates?.[0]?.content?.parts?.[0]?.text;

  if (rawText) {
    try {
      const parsed = JSON.parse(rawText);
      if (parsed.video_topic_phrase) {
        topicPhrase = parsed.video_topic_phrase;
      }
    } catch (e) {
      topicPhrase = rawText.trim();
    }
  }

  const msg = `Buenas! Te escribo desde una firma líder de servicios financieros. Llevamos tiempo siguiendo tu contenido y justo estaba viendo tu vídeo sobre ${topicPhrase}, ¡muy top! Nos gustaría proponerte una colaboración estratégica para algunas acciones que estamos preparando. ¿Tendrías un hueco esta semana y te cuento más detalles?`;

  results.push({
    influencer: `@${prepData.author || 'creador'}`,
    mensaje_personalizado: msg,
    link_video: prepData.videoUrl || '',
    transcripcion_audio: prepData.transcription || 'N/A'
  });
}

return results.map(item => ({ json: item }));
